#!/bin/bash
# UserPromptSubmit hook: one fixed reminder line (~50 tokens). No prompt parsing, no state.
echo "thinktank-check: code review / audit / brainstorm / architecture / conclusion from data -> run /thinktank:thinktank (unless the user said off this session). Text with factual claims (tax, legal, forms, deadlines, prices, entry rules) going to publication or a final review -> /thinktank:factcheck. Single answer / code edit / prose / translation / mechanical step -> do not."
